/* stateless behaviour: one shared ops table per type, no per-object bytes */
struct stream_ops { int (*read)(void *self, void *buf, unsigned n); };
static const struct stream_ops file_ops = { file_read };

struct stream {
    const struct stream_ops *ops;   /* 1 pointer */
    void *impl;                     /* 1 pointer */
};
/* sizeof(struct stream) == 2 pointers: no stateless payload at all */
